}
fn main() {
    let samples = vec![
        "x = ~ = 5;\n",          // BADNOTLHS
        "~ = 5;\n",              // BADNOTLHS bare
        "x = f(1;\n",            // NOPAR2 missing )
        "function f(\n",         // missing ) at EOF
        "function f()\n  if x\n   y=1;\nend\n",  // ENDCT2? if HAS end, function missing end
        "classdef Foo\n  function f()\n  end\nend\n",  // ENDCT4 func in classdef no methods
        "f(Name, 1);\n",         // name-value valid
        "x = 1 2;\n",            // FVSYN-ish
    ];
    let mut parser = Parser::new();
    parser.set_language(&tree_sitter_matlab::LANGUAGE.into()).unwrap();
    for (i, s) in samples.iter().enumerate() {
        let tree = parser.parse(s, None).unwrap();
        println!("===== {i}: {s:?} =====");
        dump(tree.root_node(), s, 0);
        println!();
    }
}

